@page "/catalog"
@using sv_69316cb9d7514bc492c97b37a9312a4c.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <div class="row">
        <div class="col-lg-3 col-md-4">
            <ProductFilterPanel Categories="categories"
                                OnFilterApplied="HandleFilterApplied"
                                OnFilterCleared="HandleFilterCleared" />
        </div>

        <div class="col-lg-9 col-md-8">
            @if (errorMessage is not null)
            {
                <div class="alert alert-danger mt-3" role="alert">
                    <strong>Error:</strong> @errorMessage
                </div>
            }
            else if (isLoading)
            {
                <div class="d-flex justify-content-center align-items-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else if (result is null || result.Items.Count == 0)
            {
                <div class="text-center py-5 text-muted">
                    <h4>No products found</h4>
                    <p>Try adjusting your filters.</p>
                </div>
            }
            else
            {
                <div class="d-flex justify-content-between align-items-center my-3 flex-wrap gap-2">
                    <div>
                        <select class="form-select form-select-sm" value="@sortBy"
                                @onchange="HandleSortChanged" style="min-width: 200px;">
                            <option value="price_asc">Price: Low to High</option>
                            <option value="price_desc">Price: High to Low</option>
                            <option value="name_asc">Name: A-Z</option>
                            <option value="rating_desc">Rating: Highest</option>
                        </select>
                    </div>
                    <span class="text-muted">
                        Showing @(((result.Page - 1) * result.PageSize) + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount))
                        of @result.TotalCount products
                    </span>
                </div>

                <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
                    @foreach (var product in result.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product"
                                         OnSelected="HandleProductSelected"
                                         OnAddToCart="HandleAddToCart" />
                        </div>
                    }
                </div>

                <div class="mt-4">
                    <CatalogPagination CurrentPage="currentPage"
                                       TotalPages="totalPages"
                                       OnPageChanged="HandlePageChanged" />
                </div>
            }
        </div>
    </div>
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? categories;
    private PagedResult<Product>? result;
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;
    private bool isLoading = true;
    private string? errorMessage;

    private int totalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            categories = categoriesTask.Result;
            result = productsTask.Result;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleFilterCleared()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart integration
        return Task.CompletedTask;
    }
}

